class ActorCritic(nn.Module):
    def __init__(self,  num_actor_obs,
                        num_critic_obs,
                        num_actions,
                        actor_hidden_dims=[256, 256, 256],
                        critic_hidden_dims=[256, 256, 256],
                        init_noise_std=1.0,
                        activation = nn.ELU(),
                        **kwargs):
        if kwargs:
            print("ActorCritic.__init__ got unexpected arguments, which will be ignored: " + str([key for key in kwargs.keys()]))
        super(ActorCritic, self).__init__()

        def build_trunk(input_dim, hidden_dims):
            layers = []
            prev = input_dim
            for h in hidden_dims:
                layers.append(nn.Linear(prev, h))
                layers.append(nn.LayerNorm(h))
                layers.append(nn.SiLU())
                prev = h
            return nn.Sequential(*layers)

        self.actor = build_trunk(num_actor_obs, actor_hidden_dims)
        self.critic = build_trunk(num_critic_obs, critic_hidden_dims)
        self.actor_head = nn.Linear(actor_hidden_dims[-1], num_actions)
        self.critic_head = nn.Linear(critic_hidden_dims[-1], 1)

        for mod in list(self.actor) + list(self.critic):
            if isinstance(mod, nn.Linear):
                torch.nn.init.orthogonal_(mod.weight, gain=2.0 ** 0.5)
                torch.nn.init.constant_(mod.bias, 0.0)
        torch.nn.init.orthogonal_(self.actor_head.weight, gain=0.01)
        torch.nn.init.constant_(self.actor_head.bias, 0.0)
        torch.nn.init.orthogonal_(self.critic_head.weight, gain=1.0)
        torch.nn.init.constant_(self.critic_head.bias, 0.0)

        print(f"Actor trunk: {self.actor}")
        print(f"Critic trunk: {self.critic}")

        self.std = nn.Parameter(init_noise_std * torch.ones(num_actions))
        self.std_min = 0.05
        self.std_max = 1.5
        self.mean_clip = 10.0
        self.distribution = None
        Normal.set_default_validate_args = False

    @staticmethod
    def init_weights(sequential, scales):
        [torch.nn.init.orthogonal_(module.weight, gain=scales[idx]) for idx, module in
         enumerate(mod for mod in sequential if isinstance(mod, nn.Linear))]

    def reset(self, dones=None):
        pass

    def forward(self):
        raise NotImplementedError

    @property
    def action_mean(self):
        return self.distribution.mean

    @property
    def action_std(self):
        return self.distribution.stddev

    @property
    def entropy(self):
        return self.distribution.entropy().sum(dim=-1)

    def update_distribution(self, observations):
        features = self.actor(observations)
        mean = torch.tanh(torch.clamp(self.actor_head(features), -self.mean_clip, self.mean_clip))
        std = torch.clamp(self.std, self.std_min, self.std_max)
        self.distribution = Normal(mean, mean * 0.0 + std)

    def act(self, observations, **kwargs):
        self.update_distribution(observations)
        return torch.clamp(self.distribution.rsample(), -1.0, 1.0)

    def get_actions_log_prob(self, actions):
        clipped = torch.clamp(actions, -1.0, 1.0)
        return self.distribution.log_prob(clipped).sum(dim=-1)

    def act_inference(self, observations):
        features = self.actor(observations)
        return torch.tanh(torch.clamp(self.actor_head(features), -self.mean_clip, self.mean_clip))

    def evaluate(self, critic_observations, **kwargs):
        features = self.critic(critic_observations)
        value = self.critic_head(features)
        return value

